cd ~/"Weave Takehome"/dashboard && cat > styles.css <<'CSS'
:root{
  --bg:#f4f5f7; --panel:#fff; --ink:#12151a; --ink-2:#4a5261; --ink-3:#7c8494;
  --line:#e3e6eb; --line-2:#eef0f4; --accent:#1f6feb; --good:#12855b; --warn:#b45309;
  --shadow:0 1px 2px rgba(16,20,28,.05), 0 6px 18px -10px rgba(16,20,28,.22);
  --r:10px;
  --d-feature:#2563eb; --d-reliability:#0d9488; --d-blast:#7c3aed; --d-leverage:#ea580c;
  --d-depth:#db2777; --d-ownership:#b7791f; --d-agent:#0891b2;
}
*{box-sizing:border-box}
html,body{height:100%}
body{
  margin:0; background:var(--bg); color:var(--ink); overflow:hidden;
  font:13px/1.45 -apple-system,BlinkMacSystemFont,"Segoe UI",Inter,Roboto,Helvetica,Arial,sans-serif;
  -webkit-font-smoothing:antialiased;
}
h1,h2,h3{margin:0;font-weight:650;letter-spacing:-.01em}
button{font:inherit;cursor:pointer}
a{color:var(--accent);text-decoration:none}
a:hover{text-decoration:underline}
.muted{color:var(--ink-3);font-weight:500}
.small{font-size:11px}

.app{height:100vh;display:grid;grid-template-rows:auto minmax(0,1fr);gap:10px;padding:10px 12px 12px}

/* ── header ── */
.hdr{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;padding:2px 2px 0}
.hdr h1{font-size:19px;line-height:1.2}
.repo{color:var(--accent)}
.sub{margin:3px 0 0;font-size:12px;color:var(--ink-2)}
.sub b{color:var(--ink);font-weight:650}
.hdr-right{display:flex;align-items:flex-start;gap:12px}
.chips{display:flex;flex-wrap:wrap;gap:4px;justify-content:flex-end;max-width:640px}
.chip{
  background:var(--panel);border:1px solid var(--line);border-radius:999px;
  padding:2px 8px;font-size:11px;color:var(--ink-2);white-space:nowrap;cursor:help;
}
.chip b{color:var(--ink);font-variant-numeric:tabular-nums}
.chip.ctx{background:#fbfbfd;border-style:dashed;color:var(--ink-3)}
.hdr-actions{display:flex;align-items:center;gap:8px}
.btn{
  background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:5px 10px;
  color:var(--ink);box-shadow:var(--shadow);white-space:nowrap;
}
.btn:hover{border-color:#cfd4dd}
.btn.ghost{box-shadow:none}
.link-btn{background:none;border:0;color:var(--ink-3);font-size:11px;padding:0}
.link-btn:hover{color:var(--accent)}
.mock-pill{background:#fff7e6;border:1px solid #f0c86a;color:#8a5a00;border-radius:999px;padding:3px 9px;font-size:11px;font-weight:650}

/* ── layout ── */
.main{display:grid;grid-template-columns:250px minmax(0,1fr) 350px;gap:10px;min-height:0}
.panel{background:var(--panel);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--shadow);min-height:0;display:flex;flex-direction:column}
.panel-hd{display:flex;align-items:baseline;justify-content:space-between;gap:8px;padding:10px 12px 6px}
.panel-hd h2{font-size:13px}
.hint{margin:0;padding:0 12px 8px;font-size:11px;color:var(--ink-3)}

/* ── controls ── */
.controls{overflow:hidden}
.presets{display:flex;flex-wrap:wrap;gap:4px;padding:0 12px 10px;border-bottom:1px solid var(--line-2)}
.preset{
  border:1px solid var(--line);background:#fbfbfd;border-radius:999px;padding:3px 9px;font-size:11px;color:var(--ink-2);
}
.preset:hover{border-color:#cfd4dd;color:var(--ink)}
.preset.on{background:var(--ink);border-color:var(--ink);color:#fff;font-weight:600}
.sliders{padding:8px 12px;overflow-y:auto;flex:1;display:flex;flex-direction:column;gap:9px}
.sl{display:block}
.sl-top{display:flex;align-items:baseline;justify-content:space-between;gap:6px}
.sl-label{display:flex;align-items:center;gap:6px;font-size:11.5px;font-weight:600;cursor:help}
.swatch{width:8px;height:8px;border-radius:2px;flex:none}
.sl-w{font-size:11px;color:var(--ink-3);font-variant-numeric:tabular-nums}
.sl input[type=range]{width:100%;margin:3px 0 0;height:16px;accent-color:var(--dc,#1f6feb);cursor:pointer}
.sl.off .sl-label{opacity:.45}
.controls-foot{padding:8px 12px;border-top:1px solid var(--line-2);font-size:10.5px;color:var(--ink-3)}

/* ── ranking ── */
.ranking{overflow:hidden}
.cards{flex:1;display:flex;flex-direction:column;gap:6px;padding:2px 10px 6px;min-height:0}
.card{
  flex:1;min-height:0;display:grid;grid-template-columns:24px 38px minmax(0,1fr) 176px 92px;
  align-items:center;gap:10px;padding:8px 10px;border:1px solid var(--line);border-radius:9px;
  background:#fff;cursor:pointer;transition:border-color .12s,background .12s,box-shadow .12s;
}
.card:hover{border-color:#c9d2e2;background:#fcfdff}
.card.sel{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent) inset;background:#f8fbff}
.rank{font-size:17px;font-weight:700;color:var(--ink-3);text-align:center;font-variant-numeric:tabular-nums}
.card.sel .rank{color:var(--accent)}
.avatar{width:38px;height:38px;border-radius:50%;background:#e9ecf1;border:1px solid var(--line)}
.who{min-width:0}
.who-top{display:flex;align-items:center;gap:6px;min-width:0}
.login{font-size:14px;font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.arch{font-size:10px;font-weight:650;letter-spacing:.02em;text-transform:uppercase;color:var(--ink-2);background:#f1f3f7;border:1px solid var(--line);border-radius:5px;padding:1px 5px;white-space:nowrap;cursor:help}
.delta{font-size:10px;font-weight:650;border-radius:5px;padding:1px 4px;white-space:nowrap;cursor:help}
.delta.up{color:var(--good);background:#e8f6ef}
.delta.down{color:#b02a37;background:#fdeced}
.why{margin:2px 0 0;padding:0;list-style:none;font-size:11.5px;color:var(--ink-2)}
.why li{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.why li::before{content:"— ";color:var(--ink-3)}
.bars{display:flex;align-items:flex-end;gap:4px;height:46px}
.bar{flex:1;position:relative;height:100%;display:flex;align-items:flex-end;cursor:pointer;border-radius:3px}
.bar:hover{background:#f2f4f8}
.bar i{display:block;width:100%;border-radius:2px 2px 0 0;background:var(--bc);opacity:.85;min-height:2px}
.bar.dim i{opacity:.22}
.bar.hl{background:#eef3fd}
.score{text-align:right}
.score-v{font-size:24px;font-weight:700;letter-spacing:-.02em;font-variant-numeric:tabular-nums;line-height:1;cursor:help}
.score-l{font-size:9.5px;color:var(--ink-3);text-transform:uppercase;letter-spacing:.04em;margin-top:2px}
.runners{display:flex;align-items:center;gap:6px;padding:7px 12px;border-top:1px solid var(--line-2);overflow-x:auto}
.runners .lbl{font-size:10.5px;color:var(--ink-3);white-space:nowrap}
.runner{
  display:flex;align-items:center;gap:5px;border:1px solid var(--line);background:#fbfbfd;border-radius:999px;
  padding:2px 8px 2px 3px;font-size:11px;color:var(--ink-2);white-space:nowrap;
}
.runner:hover{border-color:#cfd4dd;color:var(--ink)}
.runner.sel{border-color:var(--accent);background:#f0f6ff;color:var(--ink)}
.runner img{width:16px;height:16px;border-radius:50%}
.runner b{font-variant-numeric:tabular-nums;color:var(--ink)}

/* ── inspector ── */
.inspector{overflow-y:auto;overflow-x:hidden}
.ins-hd{display:flex;gap:9px;align-items:center;padding:10px 12px 8px;border-bottom:1px solid var(--line-2);position:sticky;top:0;background:#fff;z-index:2}
.ins-hd img{width:40px;height:40px;border-radius:50%;border:1px solid var(--line)}
.ins-hd .n{font-size:15px;font-weight:650}
.ins-hd .s{margin-left:auto;text-align:right}
.ins-hd .s b{font-size:20px;font-variant-numeric:tabular-nums}
.sec{padding:9px 12px;border-bottom:1px solid var(--line-2)}
.sec h3{font-size:10.5px;text-transform:uppercase;letter-spacing:.05em;color:var(--ink-3);margin-bottom:6px;font-weight:650}
table.math{width:100%;border-collapse:collapse;font-size:11.5px}
