/* PostHog Engineering Contribution dashboard.
   100% client-side: one JSON payload in, all re-weighting done in the browser.
   No network calls at runtime. */

const $ = (s, r = document) => r.querySelector(s);
const el = (t, c, h) => { const n = document.createElement(t); if (c) n.className = c; if (h != null) n.innerHTML = h; return n; };
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const n0 = v => Number(v ?? 0).toLocaleString('en-US');
const n1 = v => Number(v ?? 0).toFixed(1);
const pct = v => (v == null ? '—' : Math.round(v * 100) + '%');
const hrs = v => (v == null ? '—' : n1(v) + 'h');

const state = { data: null, dims: [], weights: {}, sel: null, hi: null, baseline: {} };

/* ── scoring ───────────────────────────────────────────────── */
function contributions(eng, weights) {
  const tot = state.dims.reduce((s, d) => s + (weights[d.key] || 0), 0);
  const parts = state.dims.map(d => {
    const w = weights[d.key] || 0;
    const norm = eng.norm[d.key] ?? 0;
    return { d, w, norm, raw: eng.raw?.[d.key], share: tot ? (w * norm) / tot : 0 };
  });
  return { parts, total: tot ? parts.reduce((s, p) => s + p.share, 0) : 0, wsum: tot };
}
const score = (eng, w) => contributions(eng, w).total;
const ranked = w => state.data.engineers.map(e => ({ e, s: score(e, w) }))
  .sort((a, b) => b.s - a.s || a.e.login.localeCompare(b.e.login));

/* ── tooltip ───────────────────────────────────────────────── */
const tip = $('#tip');
function moveTip(ev) {
  const pad = 14, w = tip.offsetWidth, h = tip.offsetHeight;
  let x = ev.clientX + pad, y = ev.clientY + pad;
  if (x + w > innerWidth - 8) x = ev.clientX - w - pad;
  if (y + h > innerHeight - 8) y = ev.clientY - h - pad;
  tip.style.left = Math.max(8, x) + 'px'; tip.style.top = Math.max(8, y) + 'px';
}
document.addEventListener('mousemove', ev => {
  const host = ev.target.closest('[data-tip]');
  if (!host) { tip.hidden = true; return; }
  if (tip.dataset.for !== host.dataset.tipId || tip.hidden) {
    tip.innerHTML = host.dataset.tip; tip.dataset.for = host.dataset.tipId || ''; tip.hidden = false;
  }
  moveTip(ev);
});
const tipAttr = html => `data-tip="${esc(html)}" data-tip-id="${Math.random().toString(36).slice(2)}"`;

function dimTip(d, p, eng) {
  return `<h4>${esc(d.label)}</h4>${esc(d.blurb)}
    <span class="f">${esc(d.formula)}</span>
    <div class="kv"><span>Percentile in cohort</span><b>${n1(p.norm)}</b></div>
    <div class="kv"><span>Raw value</span><b>${p.raw == null ? '—' : n1(p.raw)}</b></div>
    <div class="kv"><span>Weight</span><b>${p.w} / 5</b></div>
    <div class="kv"><span>Adds to score</span><b>${n1(p.share)}</b></div>
    <div class="note">${esc(eng.login)} ranks in the ${Math.round(p.norm)}th percentile of the ${n0(state.data.meta.eligible_engineers)} eligible engineers. Click to open the breakdown.</div>`;
}

/* ── header ────────────────────────────────────────────────── */
function renderHeader() {
  const m = state.data.meta;
  $('#scoreName').textContent = m.score_name || 'Contribution Score';
  $('#mockPill').hidden = !m.MOCK;
  document.title = `PostHog — Engineering Contribution (${m.window_start} → ${m.window_end})`;

  const c = m.counter_metrics || {};
  const chips = [
    ['merged PRs analysed', n0(m.merged_prs), `Merged PRs in the ${m.window_start} → ${m.window_end} window. Everything on this page is derived from these.`],
    ['eligible engineers', n0(m.eligible_engineers), 'Rankable if they have ≥5 merged PRs or ≥10 human reviews in the window. Percentiles are computed inside this cohort.'],
    ['bot PRs → human DRI', n0(m.bot_authored_prs), "PostHog's PR template asks the directing human to be the assignee. Bot-authored PRs are re-attributed to that DRI, so credit lands on the engineer, not posthog[bot]."],
    ['autonomous PRs excluded', n0(m.unattributed_prs), 'Bot-authored with no human assignee. No DRI to credit, so they are excluded from person scoring and reported only at org level.'],
    ['bot reviews filtered', n0(m.bot_reviews), `Reviews from greptile / copilot / codex / graphite and friends are dropped entirely. Only the ${n0(m.human_reviews)} human reviews score.`]
  ].map(([k, v, t]) => `<span class="chip" ${tipAttr(`<h4>${esc(k)}</h4>${esc(t)}`)}><b>${v}</b> ${esc(k)}</span>`);

  const ctx = [];
  if (c.revert_pct != null) ctx.push(['revert rate', n1(c.revert_pct) + '%', 'Share of merged PRs that were later reverted, across the whole repo. Context for how unusual a revert is — not part of any score.']);
  if (c.pr_lines_p50 != null) ctx.push(['PR size p50 / p90', `${n0(c.pr_lines_p50)} / ${n0(c.pr_lines_p90)}`, 'Median and 90th-percentile lines changed per PR. Shown so you can judge PR sizes — deliberately not scored, because lines of code is not impact.']);
  ctx.forEach(([k, v, t]) => chips.push(`<span class="chip ctx" ${tipAttr(`<h4>${esc(k)} — context only</h4>${esc(t)}`)}><b>${v}</b> ${esc(k)}</span>`));

  $('#metaChips').innerHTML = chips.join('');
}

function renderAnswer(rows) {
  const m = state.data.meta;
  const names = rows.slice(0, 5).map(r => `<b>${esc(r.e.login)}</b>`).join(', ');
  const preset = activePreset();
  $('#answer').innerHTML = `${names} — ranked by ${esc(m.score_name || 'Contribution Score')} over
    ${esc(m.window_start)} → ${esc(m.window_end)} under the <b>${esc(preset || 'custom')}</b> weighting.`;
}

/* ── controls ──────────────────────────────────────────────── */
function activePreset() {
  for (const [name, w] of Object.entries(state.data.presets || {}))
    if (state.dims.every(d => (w[d.key] || 0) === state.weights[d.key])) return name;
  return null;
}
function renderPresets() {
  const cur = activePreset();
  $('#presets').innerHTML = Object.keys(state.data.presets || {}).map(name => {
    const w = state.data.presets[name];
    const body = state.dims.map(d => `<div class="kv"><span>${esc(d.label)}</span><b>${w[d.key] || 0}</b></div>`).join('');
    return `<button class="preset${name === cur ? ' on' : ''}" data-preset="${esc(name)}"
      ${tipAttr(`<h4>${esc(name)}</h4>Sets all seven weights at once.${body}`)}>${esc(name)}</button>`;
  }).join('');
}
function renderSliders() {
  $('#sliders').innerHTML = state.dims.map(d => {
    const w = state.weights[d.key];
    return `<label class="sl${w === 0 ? ' off' : ''}" style="--dc:var(--d-${d.key})">
      <span class="sl-top">
        <span class="sl-label" ${tipAttr(`<h4>${esc(d.label)}</h4>${esc(d.blurb)}<span class="f">${esc(d.formula)}</span><div class="note">0 removes this dimension from the score entirely.</div>`)}>
          <i class="swatch" style="background:var(--d-${d.key})"></i>${esc(d.label)}
        </span>
        <span class="sl-w">${w}</span>
      </span>
      <input type="range" min="0" max="5" step="1" value="${w}" data-dim="${d.key}" aria-label="${esc(d.label)} weight">
    </label>`;
  }).join('');
}

/* ── ranking ───────────────────────────────────────────────── */
function cardHTML(row, i) {
  const { e, s } = row, { parts } = contributions(e, state.weights);
  const base = state.baseline[e.login], delta = base ? base - (i + 1) : 0;
  const deltaHTML = delta === 0 ? '' :
    `<span class="delta ${delta > 0 ? 'up' : 'down'}" ${tipAttr(`<h4>Rank change</h4>Ranked #${base} under the default Balanced weights, #${i + 1} under the current ones.`)}>${delta > 0 ? '▲' : '▼'}${Math.abs(delta)}</span>`;

  const bars = parts.map(p => `<span class="bar${p.w === 0 ? ' dim' : ''}${state.hi === p.d.key ? ' hl' : ''}" data-dim="${p.d.key}" data-login="${esc(e.login)}"
      style="--bc:var(--d-${p.d.key})" ${tipAttr(dimTip(p.d, p, e))}><i style="height:${Math.max(2, p.norm)}%"></i></span>`).join('');

  const scoreTip = `<h4>${esc(state.data.meta.score_name || 'Contribution Score')} = ${n1(s)}</h4>
    Weighted mean of seven percentile ranks — not a count of anything.
    <span class="f">${parts.filter(p => p.w).map(p => `${p.w}×${n1(p.norm)}`).join(' + ')}\n  ÷ ${contributions(e, state.weights).wsum} = ${n1(s)}</span>
    <div class="note">Click the row for the full breakdown, the raw values behind each percentile, and the PRs backing them.</div>`;

  return `<article class="card${state.sel === e.login ? ' sel' : ''}" data-login="${esc(e.login)}">
    <div class="rank">${i + 1}</div>
    <img class="avatar" src="${esc(e.avatar)}" alt="" loading="lazy">
    <div class="who">
      <div class="who-top">
        <span class="login">${esc(e.login)}</span>
        ${e.archetype ? `<span class="arch" ${tipAttr(`<h4>${esc(e.archetype)}</h4>A shape-of-contribution label from which dimensions they lead on. It describes the profile — it is not part of the score or the rank.`)}>${esc(e.archetype)}</span>` : ''}
        ${deltaHTML}
      </div>
      <ul class="why">${(e.why || []).slice(0, 2).map(w => `<li>${esc(w)}</li>`).join('')}</ul>
    </div>
    <div class="bars">${bars}</div>
    <div class="score">
      <div class="score-v" ${tipAttr(scoreTip)}>${n1(s)}</div>
      <div class="score-l">${esc(state.data.meta.score_name || 'score')}</div>
    </div>
  </article>`;
}

function renderCards(rows) {
  const host = $('#cards');
  const before = new Map([...host.children].map(c => [c.dataset.login, c.getBoundingClientRect().top]));
  host.innerHTML = rows.slice(0, 5).map(cardHTML).join('');
  for (const c of host.children) {                       // FLIP: make the re-sort readable
    const y = before.get(c.dataset.login);
    if (y == null) continue;
    const dy = y - c.getBoundingClientRect().top;
    if (!dy) continue;
    c.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 260, easing: 'cubic-bezier(.2,.7,.3,1)' });
  }
  const rest = rows.slice(5);
  $('#runners').innerHTML = rest.length
    ? `<span class="lbl">next up</span>` + rest.map((r, i) => `<button class="runner${state.sel === r.e.login ? ' sel' : ''}" data-login="${esc(r.e.login)}"
        ${tipAttr(`<h4>#${i + 6} ${esc(r.e.login)}</h4>Outside the top five under the current weights. Click to inspect — or raise the weight on what they are strong at and watch them move.`)}>
        <img src="${esc(r.e.avatar)}" alt=""> ${esc(r.e.login)} <b>${n1(r.s)}</b></button>`).join('')
    : '';
  $('#rankNote').textContent = `${n0(state.data.engineers.length)} shown of ${n0(state.data.meta.eligible_engineers)} eligible`;
}

/* ── inspector ─────────────────────────────────────────────── */
const STAT_TIPS = {
  merged_prs: 'Merged PRs where this engineer is the DRI (assignee if set, otherwise author).',
  feat_prs: 'Merged PRs whose conventional-commit type is feat.',
  fix_prs: 'Merged PRs typed fix.',
  perf_prs: 'Merged PRs typed perf.',
  chore_prs: 'Merged PRs typed chore. Counted, but weighted far below feature and fix work.',
  reviews_given: 'Human reviews they submitted. Bot reviews and self-reviews are excluded.',
  distinct_authors_unblocked: 'How many different engineers they reviewed for. Review Leverage uses the geometric mean of this and review volume, so reviewing many people beats reviewing one person often.',
  median_review_latency_h: 'Median hours from PR opened to their first review. Faster than the cohort median lifts Review Leverage, slower discounts it.',
  median_cycle_time_h: 'Median hours from their own PR opening to merge. Context, not scored.',
  review_followup_rate: 'Share of their reviews followed by new commits on that PR — review that actually changed the code, rather than a rubber stamp.',
  churn_rate: 'Share of their features followed within 14 days by a fix in the same area. A proxy for rework, not proof of a regression.',
  median_churn_rate: 'The cohort median churn rate, for comparison.',
  Q: 'Churn-quality factor, clamped to [0.5, 1.5]: 1 + median churn − their churn − 0.15 × reverts. It scales Reliability and Agent Leverage, so volume only counts when the work held up.',
  reverts: 'Merged PRs of theirs that were later reverted. The hard quality signal, as opposed to the churn proxy.',
  agent_assisted_prs: 'PRs where an agent helped but a human was driving.',
  agent_autonomous_prs: 'Fully autonomous agent PRs with this engineer as DRI. These carry half weight.',
  agent_share: 'Share of their merged PRs that involved an agent.',
  median_pr_lines: 'Median lines changed across their PRs. Shown for context — deliberately not scored.'
};
const statRow = (k, label, val, cls) => `<div class="st" ${tipAttr(`<h4>${esc(label)}</h4>${esc(STAT_TIPS[k] || '')}`)}>
  <span class="k">${esc(label)}</span><span class="v ${cls || ''}">${val}</span></div>`;

function renderInspector() {
  const e = state.data.engineers.find(x => x.login === state.sel) || state.data.engineers[0];
  const rows = ranked(state.weights);
  const rank = rows.findIndex(r => r.e.login === e.login) + 1;
  const { parts, total, wsum } = contributions(e, state.weights);
  const s = e.stats || {};
  const box = $('#inspector');
  const H = [];

  H.push(`<div class="ins-hd">
    <img src="${esc(e.avatar)}" alt="">
    <div>
      <div class="n"><a href="${esc(e.profile)}" target="_blank" rel="noopener">${esc(e.login)}</a></div>
      <div class="muted small">#${rank} of ${rows.length} · ${esc(e.archetype || '—')}</div>
    </div>
    <div class="s"><b>${n1(total)}</b><div class="muted small">${esc(state.data.meta.score_name || 'score')}</div></div>
  </div>`);

  // ── score math ──
  const mathRows = parts.map(p => `<tr class="${p.w === 0 ? 'zero' : ''}${state.hi === p.d.key ? ' on' : ''}" data-dim="${p.d.key}" ${tipAttr(dimTip(p.d, p, e))}>
      <td><span class="dname"><i class="swatch" style="background:var(--d-${p.d.key})"></i>${esc(p.d.label)}</span></td>
      <td>${p.w}</td><td>${n1(p.norm)}</td><td>${p.raw == null ? '—' : n1(p.raw)}</td><td>${n1(p.share)}</td></tr>`).join('');
  const bar = parts.filter(p => p.share > 0).map(p => `<span style="width:${(p.share / (total || 1)) * 100}%;background:var(--d-${p.d.key})"></span>`).join('');
  H.push(`<div class="sec">
    <h3>How this score is built</h3>
    <table class="math">
      <tr><th>Dimension</th><th>W</th><th>Pctl</th><th>Raw</th><th>Adds</th></tr>
      ${mathRows}
      <tr class="tot" ${tipAttr(`<h4>Total</h4>Σ(weight × percentile) ÷ Σ(weight) = ${n1(total)}, with Σ(weight) = ${wsum}.<div class="note">Percentile is the rank inside the eligible cohort, so 80 means "ahead of 80% of eligible engineers on this dimension" — never a count.</div>`)}>
        <td>${esc(state.data.meta.score_name || 'Score')}</td><td>${wsum}</td><td colspan="2"></td><td>${n1(total)}</td></tr>
    </table>
    <div class="contrib">${bar}</div>
  </div>`);

  // ── evidence ──
  H.push(`<div class="sec"><h3>Delivery</h3><div class="stats">
    ${statRow('merged_prs', 'merged PRs', n0(s.merged_prs))}
    ${statRow('feat_prs', 'feat', n0(s.feat_prs))}
    ${statRow('fix_prs', 'fix', n0(s.fix_prs))}
    ${statRow('perf_prs', 'perf', n0(s.perf_prs))}
    ${statRow('chore_prs', 'chore', n0(s.chore_prs))}
    ${statRow('median_cycle_time_h', 'cycle time', hrs(s.median_cycle_time_h))}
    ${s.median_pr_lines != null ? statRow('median_pr_lines', 'median PR lines', n0(s.median_pr_lines)) : ''}
  </div></div>`);

  H.push(`<div class="sec"><h3>Review</h3><div class="stats">
    ${statRow('reviews_given', 'human reviews', n0(s.reviews_given))}
    ${statRow('distinct_authors_unblocked', 'engineers unblocked', n0(s.distinct_authors_unblocked))}
    ${statRow('median_review_latency_h', 'response time', hrs(s.median_review_latency_h))}
    ${statRow('review_followup_rate', 'led to new commits', pct(s.review_followup_rate), s.review_followup_rate >= 0.5 ? 'good' : '')}
  </div></div>`);

  const churnGood = s.churn_rate != null && s.median_churn_rate != null && s.churn_rate <= s.median_churn_rate;
  H.push(`<div class="sec"><h3>Quality &amp; agents</h3><div class="stats">
    ${statRow('churn_rate', 'rework rate', pct(s.churn_rate), churnGood ? 'good' : 'bad')}
    ${statRow('median_churn_rate', 'cohort median', pct(s.median_churn_rate))}
    ${statRow('Q', 'quality factor Q', s.Q == null ? '—' : '×' + n1(s.Q), s.Q >= 1 ? 'good' : 'bad')}
    ${statRow('reverts', 'reverts', n0(s.reverts), s.reverts ? 'bad' : 'good')}
    ${statRow('agent_share', 'agent-involved', pct(s.agent_share))}
    ${statRow('agent_assisted_prs', 'agent-assisted', n0(s.agent_assisted_prs))}
    ${statRow('agent_autonomous_prs', 'autonomous', n0(s.agent_autonomous_prs))}
  </div></div>`);

  if (s.top_dirs?.length) {
    H.push(`<div class="sec"><h3>Where they work</h3><div class="dirs">${s.top_dirs.map(d => `
      <div class="dir" ${tipAttr(`<h4>${esc(d.dir)}</h4>They are the DRI on ${pct(d.share)} of the weighted work landing in this directory (${n0(d.prs)} PRs).
        <div class="kv"><span>κ — distinct engineers shipping here</span><b>${n0(d.kappa)}</b></div>
        <div class="note">κ is how load-bearing the directory is: code many engineers depend on scores higher than a private corner. It drives Blast Radius and Ownership.</div>`)}>
        <div class="dir-top"><code>${esc(d.dir)}</code><span class="muted">${pct(d.share)} · κ${n0(d.kappa)}</span></div>
        <div class="dir-bar"><i style="width:${Math.min(100, (d.share || 0) * 100)}%"></i></div>
      </div>`).join('')}</div></div>`);
  }

  if (s.key_person_flags?.length) {
    H.push(`<div class="sec"><h3>Key-person risk</h3>${s.key_person_flags.map(f => `
      <div class="flag" ${tipAttr(`<h4>Bus factor</h4>Flagged when one engineer is the DRI on ≥50% of an area's weighted work and that area has ≤3 contributors.`)}>
        <b>${esc(f.scope || f.dir)}</b> — ${pct(f.share)} of the work, ${n0(f.contributors)} contributors total.</div>`).join('')}</div>`);
  }

  H.push(`<div class="sec"><h3>Spot-check the claims</h3>${(e.evidence_prs || []).length
    ? e.evidence_prs.map(p => `<a class="pr" href="${esc(p.url)}" target="_blank" rel="noopener"
        ${tipAttr(`<h4>PR weight W = ${n1(p.W)}</h4>W = centrality × autonomy × substance. It is the unit every dimension sums — a PR into load-bearing code counts for more than the same diff in a quiet corner.
          <div class="kv"><span>κ of the directory</span><b>${n0(p.kappa)}</b></div>
          <div class="kv"><span>lines changed</span><b>${n0(p.lines)}</b></div>
          <div class="note">Opens on GitHub.</div>`)}>
        <span class="pr-t"><span class="pr-n">#${n0(p.n)}</span><span class="pr-title">${esc(p.title)}</span></span>
        <span class="pr-m"><span class="tag">${esc(p.type)}</span><span class="tag">${esc(p.dir || p.scope || '')}</span>
          <span>merged ${esc(p.merged)}</span><span>W ${n1(p.W)}</span></span>
        ${p.why ? `<span class="pr-why">${esc(p.why)}</span>` : ''}</a>`).join('')
    : '<p class="empty">No evidence PRs in this payload.</p>'}</div>`);

  box.innerHTML = H.join('');
  box.scrollTop = 0;
}

/* ── method modal ──────────────────────────────────────────── */
function renderModal() {
  const m = state.data.meta;
  const dims = state.dims.map(d => `<tr><td><b>${esc(d.label)}</b><br><span class="muted small">${esc(d.blurb)}</span></td><td class="f">${esc(d.formula)}</td></tr>`).join('');
  const pk = state.dims.map(d => `<th>${esc(d.label.split(' ')[0])}</th>`).join('');
  const pr = Object.entries(state.data.presets || {}).map(([name, w]) =>
    `<tr><td>${esc(name)}</td>${state.dims.map(d => `<td>${w[d.key] ?? 0}</td>`).join('')}</tr>`).join('');
  $('#modalBody').innerHTML = `
    <h3>The claim</h3>
    <p>Impact is not lines, commits or PR count. This model scores seven things an engineering leader actually
    cares about, each one weighted by <b>how load-bearing the touched code is</b>, then reports every engineer's
    <b>percentile rank</b> on each — so a number like 82 means "ahead of 82% of the eligible cohort", never "82 of something".</p>

    <h3>Who gets the credit</h3>
    <p>DRI(pr) = first assignee, falling back to the author. PostHog's PR template asks the directing human to be
    the assignee, so agent-authored PRs still credit the engineer who drove them. ${n0(m.bot_authored_prs)} PRs were
    re-attributed this way; ${n0(m.unattributed_prs)} fully autonomous PRs with no human assignee are excluded from
    person scoring. All ${n0(m.bot_reviews)} bot reviews are filtered out — only the ${n0(m.human_reviews)} human
    reviews score. An engineer is eligible with ≥5 merged PRs or ≥10 reviews: ${n0(m.eligible_engineers)} qualify.</p>

    <h3>Per-PR weight</h3>
    <p><code>W(pr) = C × A × G</code> — <b>C</b> centrality, 0.6–2.0, from κ, the number of distinct engineers
    shipping into that area; <b>A</b> autonomy, 1.0 human-driven or agent-assisted, 0.5 fully autonomous;
    <b>G</b> substance, 0.4 for a one-line one-file change, else 1.0. Every dimension sums W, never a raw count.</p>

    <h3>The seven dimensions</h3>
    <table><tr><th>Dimension</th><th>Formula</th></tr>${dims}</table>

    <h3>Normalisation and the composite</h3>
    <p>Each raw dimension is mapped to its percentile inside the eligible cohort (percentile rather than z-score —
    the distributions are heavily right-skewed), then
    <code>${esc(m.score_name || 'Score')} = Σ(w<sub>d</sub> × pctl<sub>d</sub>) ÷ Σ(w<sub>d</sub>)</code>, w ∈ [0,5].
    Raw values sit beside every percentile in the inspector.</p>

    <h3>Presets</h3>
    <table><tr><th>Preset</th>${pk}</tr>${pr}</table>

    <h3>What is deliberately not scored</h3>
    <p>Lines changed and PR size appear only as context (repo median ${n0((m.counter_metrics || {}).pr_lines_p50)},
    p90 ${n0((m.counter_metrics || {}).pr_lines_p90)}). Commit counts are absent entirely.</p>

    <h3>Known caveats</h3>
    <p>Rework rate is a <b>proxy</b>: a fix landing in the same area within 14 days is not proof of a regression —
    reverts are the hard signal, and both are shown. Ownership is two-signed: it rewards holding a critical area and
    simultaneously flags the continuity risk of that. Review depth counts inline comments with a 0.6 exponent, so a
    nitpick storm cannot dominate. Work that never becomes a PR — design, incident response, mentoring — is invisible
    to any repo-derived model, this one included.</p>

    <p class="muted small">Window ${esc(m.window_start)} → ${esc(m.window_end)} · ${n0(m.merged_prs)} merged PRs ·
    generated ${esc(m.generated_at)}${m.MOCK ? ' · MOCK PAYLOAD' : ''}</p>`;
  $('#modal').hidden = false;
}

/* ── render + events ───────────────────────────────────────── */
function render() {
  const rows = ranked(state.weights);
  if (!state.sel) state.sel = rows[0].e.login;
  renderPresets(); renderSliders(); renderCards(rows); renderInspector(); renderAnswer(rows);
}

function wire() {
  $('#sliders').addEventListener('input', ev => {
    const k = ev.target.dataset.dim; if (!k) return;
    state.weights[k] = +ev.target.value; state.hi = k;
    render();
  });
  $('#presets').addEventListener('click', ev => {
    const b = ev.target.closest('[data-preset]'); if (!b) return;
    Object.assign(state.weights, state.data.presets[b.dataset.preset]); state.hi = null; render();
  });
  $('#resetBtn').addEventListener('click', () => {
    state.dims.forEach(d => state.weights[d.key] = d.default_weight ?? 3);
    state.hi = null; render();
  });
  document.addEventListener('click', ev => {
    const bar = ev.target.closest('.bar');
    if (bar) { state.sel = bar.dataset.login; state.hi = bar.dataset.dim; render(); return; }
    const card = ev.target.closest('.card, .runner');
    if (card) { state.sel = card.dataset.login; render(); return; }
    const mrow = ev.target.closest('#inspector tr[data-dim]');
    if (mrow) { state.hi = state.hi === mrow.dataset.dim ? null : mrow.dataset.dim; render(); }
  });
  $('#methodBtn').addEventListener('click', renderModal);
  $('#modalClose').addEventListener('click', () => $('#modal').hidden = true);
  $('#modal').addEventListener('click', ev => { if (ev.target.id === 'modal') $('#modal').hidden = true; });
  document.addEventListener('keydown', ev => {
    if (ev.key === 'Escape') { $('#modal').hidden = true; return; }
    if (ev.key !== 'ArrowDown' && ev.key !== 'ArrowUp') return;
    const rows = ranked(state.weights);
    const i = rows.findIndex(r => r.e.login === state.sel);
    const j = Math.min(rows.length - 1, Math.max(0, i + (ev.key === 'ArrowDown' ? 1 : -1)));
    if (j !== i) { ev.preventDefault(); state.sel = rows[j].e.login; render(); }
  });
}

async function boot() {
  let data = null;
  try {                                            // static JSON when served over http
    const r = await fetch('dashboard_data.json', { cache: 'no-cache' });
    if (r.ok) data = await r.json();
  } catch (_) { /* file:// — fall through */ }
  data = data || window.__DASHBOARD_DATA__;
  if (!data) { document.body.innerHTML = '<p style="padding:40px">No data payload. Run <code>./build.sh</code>.</p>'; return; }

  state.data = data;
  state.dims = data.dimensions;                    // dimensions[] order IS the slider order
  state.dims.forEach(d => state.weights[d.key] = d.default_weight ?? 3);
  const baseW = {}; state.dims.forEach(d => baseW[d.key] = d.default_weight ?? 3);
  ranked(baseW).forEach((r, i) => state.baseline[r.e.login] = i + 1);

  renderHeader(); wire(); render();
}
boot();
