:root{
  --bg:#0a0c10; --panel:#12151b; --panel-2:#171b23; --ink:#e8ecf4; --ink-2:#9aa4b6; --ink-3:#6b7488;
  --line:#232936; --line-2:#1b202a; --accent:#5b9dff; --good:#34d399; --bad:#f87171;
  --r:12px;
  --d-feature:#5b9dff; --d-reliability:#2dd4bf; --d-blast:#a78bfa; --d-leverage:#fb923c;
  --d-depth:#f472b6; --d-ownership:#eab308; --d-agent:#22d3ee;
}
*{box-sizing:border-box}
html,body{height:100%}
body{
  margin:0;background:var(--bg);color:var(--ink);overflow:hidden;
  font:13px/1.45 -apple-system,BlinkMacSystemFont,"Segoe UI",Inter,Roboto,Helvetica,Arial,sans-serif;
  -webkit-font-smoothing:antialiased;
}
h1,h2,h3{margin:0;font-weight:620;letter-spacing:-.01em}
button{font:inherit;cursor:pointer;color:inherit}
