::-webkit-scrollbar{width:8px;height:8px}
::-webkit-scrollbar-thumb{background:#252b38;border-radius:8px}
::-webkit-scrollbar-track{background:transparent}

.app{height:100vh;display:grid;grid-template-rows:auto minmax(0,1fr);gap:12px;padding:14px 16px 16px}

/* ── header ── */
.hdr{display:flex;align-items:flex-start;justify-content:space-between;gap:24px}
.hdr h1{font-size:20px;line-height:1.2}
.repo{color:var(--accent)}
