.btn{background:var(--panel-2);border:1px solid var(--line);border-radius:9px;padding:7px 12px;white-space:nowrap}
.btn:hover{border-color:#31394a;background:#1b2029}
.btn b{color:var(--ink);font-weight:620}
.btn .ico{color:var(--ink-3);margin-right:2px}
.btn.ghost{background:transparent;color:var(--ink-2)}
.btn.on{border-color:var(--accent);color:#fff}
.link-btn{background:none;border:0;color:var(--ink-3);font-size:11px;padding:0}
.link-btn:hover{color:var(--accent)}

/* ── weights popover ── */
.pop{
  position:absolute;top:42px;right:0;width:328px;z-index:50;background:var(--panel);
  border:1px solid var(--line);border-radius:var(--r);box-shadow:0 24px 60px -18px rgba(0,0,0,.8);padding:12px;
}
