.presets{display:flex;flex-wrap:wrap;gap:5px;padding-bottom:11px;border-bottom:1px solid var(--line-2)}
.preset{border:1px solid var(--line);background:var(--panel-2);border-radius:999px;padding:4px 10px;font-size:11px;color:var(--ink-2)}
.preset:hover{border-color:#31394a;color:var(--ink)}
.preset.on{background:var(--accent);border-color:var(--accent);color:#06101f;font-weight:640}
.sliders{padding:11px 0 0;display:flex;flex-direction:column;gap:11px}
.sl-top{display:flex;align-items:baseline;justify-content:space-between}
.sl-label{display:flex;align-items:center;gap:7px;font-size:11.5px;font-weight:600;cursor:help}
.swatch{width:8px;height:8px;border-radius:2px;flex:none}
.sl-w{font-size:11px;color:var(--ink-3);font-variant-numeric:tabular-nums}
