.sl.off .sl-label{opacity:.4}
.pop-foot{margin-top:11px;padding-top:9px;border-top:1px solid var(--line-2);font-size:10.5px;color:var(--ink-3)}

/* ── layout ── */
.main{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.02fr);gap:12px;min-height:0}
.panel{background:var(--panel);border:1px solid var(--line);border-radius:var(--r);min-height:0;display:flex;flex-direction:column}
.panel-hd{display:flex;align-items:baseline;justify-content:space-between;padding:11px 14px 7px}
.panel-hd h2{font-size:13px}

/* ── leaderboard ── */
.board{overflow:hidden}
.cards{flex:1;display:flex;flex-direction:column;gap:7px;padding:2px 11px 7px;min-height:0}
.card{
  flex:1;min-height:0;overflow:hidden;display:grid;grid-template-columns:20px 40px minmax(0,1fr) 92px;
  align-items:center;gap:12px;padding:10px 13px;border:1px solid var(--line);border-radius:10px;
  background:var(--panel-2);cursor:pointer;transition:border-color .13s,background .13s;
}
.card:hover{border-color:#333c4e;background:#1a1f28}
.card.sel{border-color:var(--accent);background:#151d2b}
.rank{font-size:18px;font-weight:700;color:var(--ink-3);text-align:center;font-variant-numeric:tabular-nums}
.card.sel .rank{color:var(--accent)}
.avatar{width:40px;height:40px;border-radius:50%;background:#1c212b;border:1px solid var(--line);object-fit:cover}
.avatar.fb,.runner img.fb,.ins-hd img.fb{display:flex;align-items:center;justify-content:center;font-weight:700;color:var(--ink-2);background:#1c212b;font-size:15px}
.who{min-width:0}
