.login{font-size:14.5px;font-weight:640;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.arch{font-size:9.5px;font-weight:650;letter-spacing:.04em;text-transform:uppercase;color:var(--ink-2);background:#1e2430;border:1px solid var(--line);border-radius:5px;padding:1.5px 6px;white-space:nowrap;cursor:help}
.delta{font-size:10px;font-weight:650;border-radius:5px;padding:1px 5px;white-space:nowrap;cursor:help}
.delta.up{color:var(--good);background:rgba(52,211,153,.12)}
.delta.down{color:var(--bad);background:rgba(248,113,113,.12)}
.why{margin:3px 0 0;padding:0;list-style:none;font-size:11px;line-height:1.4;color:var(--ink-2);cursor:help}
.why li{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.mix{display:flex;height:5px;border-radius:3px;overflow:hidden;background:#1c212b;margin-top:7px;cursor:help}
.mix span{display:block;height:100%}
.score{text-align:right}
.score-v{font-size:25px;font-weight:700;letter-spacing:-.025em;font-variant-numeric:tabular-nums;line-height:1;cursor:help}
.score-l{font-size:9px;color:var(--ink-3);text-transform:uppercase;letter-spacing:.05em;margin-top:3px}
.runners{display:flex;align-items:center;gap:6px;padding:8px 13px;border-top:1px solid var(--line-2);overflow-x:auto}
