.runner{display:flex;align-items:center;gap:6px;border:1px solid var(--line);background:var(--panel-2);border-radius:999px;padding:3px 10px 3px 4px;font-size:11px;color:var(--ink-2);white-space:nowrap;flex:none}
.runner:hover{border-color:#333c4e;color:var(--ink)}
