.detail{overflow-y:auto;overflow-x:hidden}
.ins-hd{display:flex;gap:11px;align-items:center;padding:12px 14px 11px;border-bottom:1px solid var(--line-2);position:sticky;top:0;background:var(--panel);z-index:3}
.ins-hd img{width:44px;height:44px;border-radius:50%;border:1px solid var(--line)}
.ins-hd .n{font-size:16px;font-weight:640}
.ins-hd .s{margin-left:auto;text-align:right;cursor:help}
.ins-hd .s b{font-size:23px;font-variant-numeric:tabular-nums;letter-spacing:-.02em}
.ins-hd .s .hint{font-size:9.5px;color:var(--ink-3);text-transform:uppercase;letter-spacing:.05em}
.sec{padding:11px 14px;border-bottom:1px solid var(--line-2)}
.sec h3{font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:var(--ink-3);margin-bottom:8px;font-weight:640}
.chartsec{display:grid;grid-template-columns:200px minmax(0,1fr);gap:12px;align-items:center}
.chart-wrap{height:186px;margin-left:-6px}
.recharts-wrapper{cursor:default}

table.math{width:100%;border-collapse:collapse;font-size:11.5px}
table.math th{font-weight:600;color:var(--ink-3);text-align:right;padding:0 0 4px;font-size:9.5px;text-transform:uppercase;letter-spacing:.04em}
table.math th:first-child{text-align:left}
table.math td{padding:3.5px 0;border-top:1px solid var(--line-2);text-align:right;font-variant-numeric:tabular-nums}
