table.math tbody tr:hover td{background:#181d26}
table.math tr.on td{background:#1a2333}
table.math tr.tot td{border-top:1px solid var(--line);font-weight:700;color:#fff}
table.math tr.zero td{opacity:.42}
.dname{display:flex;align-items:center;gap:7px}

.stats{display:grid;grid-template-columns:1fr 1fr;gap:5px 14px}
.st{display:flex;justify-content:space-between;gap:8px;font-size:11.5px;padding:2px 0;border-bottom:1px solid var(--line-2);cursor:help}
.st .k{color:var(--ink-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.st .v{font-weight:640;font-variant-numeric:tabular-nums;white-space:nowrap}
.st .v.good{color:var(--good)}
.st .v.bad{color:var(--bad)}
.dirs{display:flex;flex-direction:column;gap:7px}
.dir{font-size:11.5px;cursor:help}
