.dir-bar{height:4px;background:#1c212b;border-radius:3px;margin-top:4px;overflow:hidden}
.dir-bar i{display:block;height:100%;background:var(--d-ownership);border-radius:3px}
.flag{background:rgba(234,179,8,.09);border:1px solid rgba(234,179,8,.3);border-radius:8px;padding:7px 9px;font-size:11.5px;color:#f0d68a;margin-bottom:6px;cursor:help}
.pr{display:block;padding:7px 0;border-top:1px solid var(--line-2);font-size:11.5px}
.pr:first-child{border-top:0}
.pr:hover{text-decoration:none;background:#171c25}
.pr-t{display:flex;gap:7px;align-items:baseline}
.pr-n{color:var(--accent);font-weight:640;font-variant-numeric:tabular-nums}
.pr-title{color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1}
.pr-m{display:flex;gap:7px;flex-wrap:wrap;color:var(--ink-3);font-size:10.5px;margin-top:3px}
.pr-m .tag{background:#1a1f29;border-radius:5px;padding:0 5px}
.pr-why{color:var(--ink-2);font-size:11px;margin-top:2px;font-style:italic}
.empty{color:var(--ink-3);font-size:11.5px;font-style:italic}

/* ── tooltip ── */
.tooltip{
  position:fixed;z-index:80;max-width:340px;background:#0b0e14;border:1px solid #2b3242;color:var(--ink);
  border-radius:9px;padding:9px 11px;font-size:11.5px;line-height:1.5;pointer-events:none;
  box-shadow:0 18px 44px -14px rgba(0,0,0,.9);
}
