.tooltip .f{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:10.5px;background:#151a23;border:1px solid #232a36;border-radius:6px;padding:5px 7px;margin:6px 0 0;display:block;white-space:pre-wrap;color:#9fc6ff}
.tooltip .kv{display:flex;justify-content:space-between;gap:16px;margin-top:3px;color:var(--ink-2)}
.tooltip .kv b{color:#fff;font-variant-numeric:tabular-nums}
.tooltip .note{margin-top:6px;color:var(--ink-3);font-size:10.5px}

/* ── modal ── */
.modal[hidden]{display:none!important}
.modal{position:fixed;inset:0;background:rgba(4,6,10,.72);display:flex;align-items:center;justify-content:center;z-index:90;padding:28px}
.modal-card{background:var(--panel);border:1px solid var(--line);border-radius:14px;max-width:860px;width:100%;max-height:86vh;display:flex;flex-direction:column}
.modal-hd{display:flex;justify-content:space-between;align-items:center;padding:15px 18px;border-bottom:1px solid var(--line)}
.modal-hd h2{font-size:15px}
.modal-body{padding:16px 18px;overflow-y:auto;font-size:12.5px;line-height:1.65;color:var(--ink-2)}
.modal-body h3{font-size:10.5px;text-transform:uppercase;letter-spacing:.06em;color:var(--ink-3);margin:18px 0 7px}
.modal-body h3:first-child{margin-top:0}
.modal-body p{margin:0 0 9px}
.modal-body b{color:var(--ink)}
.modal-body code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11.5px;background:#171c25;padding:1.5px 5px;border-radius:5px;color:#9fc6ff}
.modal-body table{width:100%;border-collapse:collapse;font-size:11.5px;margin:5px 0 10px}
.modal-body td,.modal-body th{border-bottom:1px solid var(--line-2);padding:6px 7px;text-align:left;vertical-align:top}
.modal-body th{color:var(--ink-3);font-size:10px;text-transform:uppercase;letter-spacing:.04em}
