.modal-body .fact{background:var(--panel-2);border:1px solid var(--line);border-radius:9px;padding:9px 11px}
.modal-body .fact b{display:block;font-size:17px;color:#fff;font-variant-numeric:tabular-nums;letter-spacing:-.02em}
.modal-body .fact span{font-size:10.5px;color:var(--ink-3)}

@media (max-height:760px){
  .why li{-webkit-line-clamp:1}
  .chart-wrap{height:160px}
  .avatar{width:34px;height:34px}
}
