p='aggregate.py'; s=open(p).read()
old = """# ---------- churn ----------
fixes_by_dir = defaultdict(list)
for n,p in attributed.items():
    if p['_type'] in ('fix','perf'):
        for d in p['_dirs']: fixes_by_dir[d].append(ts(p['ma']))
for v in fixes_by_dir.values(): v.sort()

def churned(p):
    t0 = ts(p['ma']); t1 = t0 + timedelta(days=CHURN_DAYS)
    for d in p['_dirs']:
        for tf in fixes_by_dir.get(d, []):
            if t0 < tf <= t1: return True
    return False
"""
new = '''# ---------- churn ----------
# Directory granularity was useless here: in a monorepo this size *some* fix lands in
# products/… within 14 days of every feature, so the median churn rate came out at 1.00
# and Q(e) collapsed to a constant. File-level is the tighter, defensible claim:
# a fix/perf PR that touches a file this feature changed, inside the window.
import bisect
file_fix_times = defaultdict(list)
for n, p in attributed.items():
    if p['_type'] in ('fix', 'perf'):
        t = ts(p['ma'])
        for f in (files.get(n, {}).get('f') or []):
            if is_gen(f['p']): continue
            file_fix_times[f['p']].append((t, n))
for v in file_fix_times.values(): v.sort(key=lambda x: x[0])
fix_times_only = {k: [t for t, _ in v] for k, v in file_fix_times.items()}

def churned(p):
    t0 = ts(p['ma']); t1 = t0 + timedelta(days=CHURN_DAYS); me = p['n']
    for f in (files.get(me, {}).get('f') or []):
        if is_gen(f['p']): continue
        arr = file_fix_times.get(f['p'])
        if not arr: continue
        times = fix_times_only[f['p']]
        i = bisect.bisect_right(times, t0)
        while i < len(arr) and arr[i][0] <= t1:
            if arr[i][1] != me: return True
            i += 1
    return False
'''
assert old in s
s = s.replace(old, new)
open(p,'w').write(s)
print("patched")
